import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    if dtype.is_floating_point:
        x = torch.empty(shape, dtype=dtype, device=device).uniform_(0.99, 1.01)
    elif dtype is torch.bool:
        x = torch.randint(0, 2, shape, dtype=torch.int8, device="cpu").to(
            device, dtype=dtype
        )
    elif dtype is torch.uint8:
        x = torch.randint(0, 4, shape, dtype=dtype, device="cpu").to(device)
    else:
        x = torch.randint(-3, 4, shape, dtype=dtype, device="cpu").to(device)
    return {"x": x}


def run(x, dim, out_dtype):
    dt = getattr(torch, out_dtype)
    if x.dtype is torch.bool:
        ref = x.to(torch.uint8)
    elif x.is_floating_point():
        ref = x.to(torch.float64)
    else:
        ref = x
    return torch.cumprod(ref, dim=dim, dtype=dt)
